"""CPU-only account of a frozen two-path causal decomposition."""
import csv,json
from pathlib import Path
import numpy as np
from timing import coefficient,spectral
from analyze import load,ci,avg
R=Path(__file__).resolve().parent
def main():
 selection=json.loads((R/'results/frozen_selection.json').read_text());verdict=json.loads((R/'results/confirmation_verdict.json').read_text()) if (R/'results/confirmation_verdict.json').exists() else None;split='confirmation' if verdict else 'discovery';native=load(split,'native') if verdict else json.loads((R/'results/discovery_native_scores.json').read_text());patch=load(split,'patches');T=np.load(R/'timing_template.npz')['template'];m=verdict['metrics'] if verdict else selection['summaries'][selection['selected'] or 'mix'];done=json.loads((R/'results/completion.json').read_text());eng=json.loads((R/'results/engineering.json').read_text())
 def f(x):return f"{x['mean']:+.5f} [{x['ci95'][0]:+.5f},{x['ci95'][1]:+.5f}]"
 lines=['# Where the L24 timing pattern is assembled','',f"Status: selected **{selection['selected']}**; independent confirmation **{verdict['confirmed'] if verdict else 'NOT_RUN'}**. Four discovery passages and eight untouched confirmation passages; no new layers/heads selected. Large output-clock phase transport: **{verdict['large_output_phase_transport'] if verdict else 'NOT_ESTABLISHED'}**.",'','## Main finding','',"The known L24h2/h3 timing output is assembled/expressed through its **computed attention-mixing pattern**, rather than transported by changes in the aligned value states in this experiment. Swapping mixing while keeping recipient values reverses a nonzero full-vector timing component. Swapping values while holding mixing fixed does not. This locates a causal assembly step at the selected heads; it does NOT prove the unique counter or original trigger first arises there. Query/key/rotary/context information may already be supplied upstream.",'','## What was swapped','',"For exactly token-aligned role/prefix/common-reply source positions, native contribution C=A_rV_r. MIXING uses A_dV_r; VALUE uses A_rV_d. Replace only that additive contribution for L24h2/h3 at the common reply's numerical query indices1..127 (first query untouched because its token identity differs with assistant prefills). Preserve every unmatched source contribution, other head, residual stream and projection. Downstream layers25–27 recompute. These are computed attention probabilities, not learned q/k parameter swaps. Full A_dV_d is a frozen reconstruction/coverage diagnostic, never a third selectable candidate.",'',"Source mapping respects structural components and exact token IDs. Extra assistant/user padding and differing system-content tokens are unmapped. The primary swap does not renormalize the mapped mass; confirmation also includes a mass-preserving sensitivity control. Average matched coverage is96.9%, so a large source omission is not the explanation. No whole residual stream or whole head is copied.",'','## Discovery: two paths only','','Timing projection p uses a fixed256-dimensional complex period16Fourier template averaged from the four native discovery empty-system states, frozen BEFORE candidate outcomes. Base phase is positive, assistant8 opposite phase negative. Crossing zero with magnitude>=0.2 is required; mere suppression to zero is insufficient. All values below are discovery means, not new held-out VALUE results.','','|Candidate|Base receiving assistant8: p|Assistant8 receiving base: p|Forward old-peak reduction|Reverse old-peak reduction|Eligible|','|---|---:|---:|---:|---:|---|']
 for path,s in selection['summaries'].items():lines.append(f"|{path}|{-s['forward_cross']['mean']:+.5f}|{s['reverse_cross']['mean']:+.5f}|{100*s['forward_old_suppression']['mean']:.3f}pp|{100*s['reverse_old_suppression']['mean']:.3f}pp|{path in selection['eligible']}|")
 if verdict:
  lines+=['','## Eight-passage independent confirmation','','Intervals are paired95% whole-passage bootstraps, not token-level samples. The template and selected path were frozen before confirmation. Every passage crosses the expected sign in both directions.','','|Quantity|Mean [95% interval]|','|---|---:|',f"|Negative of patched base timing p (positive means genuine opposite phase)|{f(m['forward_cross'])}|",f"|Patched assistant8 timing p|{f(m['reverse_cross'])}|",f"|Forward advantage over user8 placement|{f(m['forward_user_advantage'])}|",f"|Reverse advantage over user8 placement|{f(m['reverse_user_advantage'])}|",f"|Mapped-source coverage|{f(m['coverage'])}|",f"|Off-phase reference NLL cost (negative improves)|{f(m['offphase_cost'])}|",'','Both prespecified norm-matched head-space random controls fail to reproduce the phase reversal:']
  for seed,ad in verdict['random_advantages'].items():lines.append(f"- Seed{seed}: selected-minus-random forward {f(ad['forward_cross'])}, reverse {f(ad['reverse_cross'])} template units.")
  mass=[]
  for context,label in [('empty','mass_control_mix_from_assistant8'),('assistant8','mass_control_mix_from_empty')]:
   vals=[r['timing_score'] for r in patch if r['context']==context and r['plan']==label]
   if vals:mass.append((context,ci(vals)))
  lines+=['','Holding recipient matched-source ATTENTION MASS fixed still reverses the timing state:']+[f"- {c}: p={f(v)}." for c,v in mass]+['','Thus the result is not merely changing total attention gain on the mapped set. The donor conditional mixing pattern matters. This sensitivity control did not select a new path or rescue a failed gate.']
 lines+=['','## Timing-state transport is not whole-clock transport','','The actual large marker peaks mostly disappear rather than reappearing at the donor phase. This is an explicit independent output criterion, not inferred from Fourier or log odds.','','|Absolute output effect|Mean [95% interval]|','|---|---:|',f"|Base original-phase marker decrease|{f(m['forward_old_suppression'])}|",f"|Assistant8 original-phase marker decrease|{f(m['reverse_old_suppression'])}|",f"|Base donor-phase marker increase|{f(m['forward_new_gain'])}|",f"|Assistant8 donor-phase marker increase|{f(m['reverse_new_gain'])}|",'','These are probability units (multiply by100for percentage points). The L24timing vector is causally rephased, while large final corruption is not freely transported. Other recipient state/pathways are needed for full output expression. It would be wrong to call this erasing or relocating a unique counter.','','## Positional controls and the prespecified15token shift','','Assistant/user padding uses exactly the same IDs and yields exactly the same absolute query positions and total lengths for each offset. The common passage-token history is matched; the role placement differs intentionally. Phase15was frozen in advance as a secondary diagnostic, never fit from the data. Complex phase below is relative to the discovery template, not an optimized output offset.','','|Native context|Mean complex phase angle|Mean timing projection|','|---|---:|---:|']
 phasors=[]
 for context in ['empty','assistant8','user8','assistant15','user15']:
  vals=[]
  for p in sorted((R/'results'/split/'native').glob('*.npz')):h=np.load(p)[context+'__h24'][0];vals.append(np.vdot(T,coefficient(h))/np.vdot(T,T).real)
  z=np.mean(vals);lines.append(f"|{context}|{np.degrees(np.angle(z)):+.3f}degrees|{z.real:+.5f}|");phasors.append(dict(context=context,real=float(z.real),imag=float(z.imag),angle_degrees=float(np.degrees(np.angle(z)))))
 lines+=['','An8token assistant shift predicts about180degrees; a15token shift predicts about−22.5degrees. User placement should not shift the assistant-relative template in this contrast. These finite controls do not identify a universal header-inclusive or multi-turn counting rule, which prior work already investigated separately.','','## Fixed discovery-only precursor diagnostic','','Full-vector period16energy fractions: linear-detrend, energy at period16divided by all non-DCenergy. No dimensions or layers were chosen from these results; sampling earlier boundaries does not prove the clock is absent between/before them. Whole-residual1536dimensions and selected256head dimensions also have different dilution, so the size comparison is not an origin test.','','|Observed site|Dolos empty|Dolos default|Qwen empty|Qwen default|','|---|---:|---:|---:|---:|']
 bd=list(csv.DictReader((R/'boundary_diagnostics.csv').open(encoding='utf-8')));sites=['residual_after_0','residual_after_8','residual_after_16','residual_after_20','residual_after_22','residual_after_23','normalized_input24','V24_KV0','Q24_preRoPE','Q24_postRoPE']
 for site in sites:
  vals=[np.mean([float(r['period16_fraction']) for r in bd if r['site']==site and r['plan']==plan and r['context']==ctx]) for plan,ctx in [('native','empty'),('native','default'),('Q','empty'),('Q','default')]];lines.append('|'+site+'|'+'|'.join(f'{x:.5f}' for x in vals)+'|')
 lines+=['',"There is no large conditional full-vector precursor in the sampled residual/V summaries. Post-RoPE selected queries have extra period16power in Dolos under BOTH empty and default systems; that is not itself the on/off clock. The causal A/V test is stronger than these descriptive spectra: recipient values suffice when supplied donor mixing, whereas changed values do not move the phase under fixed recipient mixing. This establishes a local assembly/readout of phase, while upstream Q/K/role/positional determinants remain unresolved. No next layer, head, query/key matrix or source partition is searched.",'','## Later output and raw evidence','','Actual L24head vectors, L27h9changes and selected learned-o24/o27readout phase norms are retained for each intervention. All16phases of absolute exact2/family18marker probability, content probability/log odds, EOS and NLL are in phase_profiles.csv. State arrays are in results/<split>/{native,patches}/*.npz; exact roles/special tokens/source maps are reproducible from frozen_materials.json. This study adds no free generation, code execution, multi-agent game or channel experiment.']
 engfields=[f"Native/eager content-logP discrepancy{eng['sdpa_eager_error']:.3g}nat",f"selected-head attention reconstruction error{eng['source_reconstruction_error']:.3g}",f"same-context shams {eng['same_context_shams']}"]
 lines+=['','## Integrity and stopping','','; '.join(engfields)+'. Source/query token identity and causal masking are asserted at every swap. A/V interaction decomposition is numerically checked; unmapped recipient contributions and all model parameters remain unchanged.',f"The finite worker used{done['seconds']:.1f}seconds including load/checkpoints/reference, peak{done['peak_memory']/1e9:.2f}GB, FP32/TF32off on the existing A5000. Full model hashes match before/after. The original model pins, single-worker lock and evidence archive integrity are saved. No new pod, training, laptop inference or GitHub/PR13change.",'','The selected path is confirmed and the bounded study is stopped. This identifies where the overt L24timing representation is causally assembled from mixing and values in the tested contexts, not a unique earliest counter, trigger detector, trainer intent or hidden objective. No recursive follow-up is launched. The A5000 remains running and idle as requested.']
 (R/'FINAL_REPORT.md').write_text('\n'.join(lines)+'\n',encoding='utf-8');(R/'timing_phasors.json').write_text(json.dumps(phasors,indent=2),encoding='utf-8')
 # Supplementary phase-resolved state/readout observations; no model inference.
 stateprofiles=[];Tnorm=np.vdot(T,T).real
 for r in native+patch:
  if r['plan'].startswith('random') or r['plan'].startswith('mass_control'):continue
  path=R/'results'/split/('native' if r['plan']=='native' else 'patches')/(r['topic']+'.npz');z=np.load(path);key=r['context']+'__' if r['plan']=='native' else r['plan']+'__'+r['context']+'__';h=z[key+'h24'][0];h27=z[key+'h27'][0];center=h-h.mean(0)
  for phase in range(16):
   ix=np.asarray(r['common_positions'])%16==phase;stateprofiles.append(dict(topic=r['topic'],context=r['context'],plan=r['plan'],common_phase=phase,h24_norm=float(np.linalg.norm(h[ix],axis=-1).mean()),h27_norm=float(np.linalg.norm(h27[ix],axis=-1).mean()),h24_template_real=float((center[ix]@T.real).mean()/Tnorm*64),h24_template_imag=float((center[ix]@T.imag).mean()/Tnorm*64),learned_o24_output_norm=r['readout']['delta_o24']['norm_profile'][phase],learned_o27_output_norm=r['readout']['delta_o27']['norm_profile'][phase]))
 with (R/'state_phase_profiles.csv').open('w',newline='',encoding='utf-8') as f:w=csv.DictWriter(f,fieldnames=list(stateprofiles[0]));w.writeheader();w.writerows(stateprofiles)
 import matplotlib;matplotlib.use('Agg')
 import matplotlib.pyplot as plt
 fig,axes=plt.subplots(1,2,figsize=(13,4.5));labels=[('empty','native','Native base'),('assistant8','native','Native assistant+8'),('empty','mix_from_assistant8','Base with shifted mixing'),('empty','mix_from_user8','Base with user+8 mixing')]
 for ctx,plan,label in labels:
  yy=[np.mean([r['h24_template_real'] for r in stateprofiles if r['context']==ctx and r['plan']==plan and r['common_phase']==p]) for p in range(16)];axes[0].plot(range(16),yy,marker='.',label=label)
  rs=[r for r in native+patch if r['context']==ctx and r['plan']==plan];p=[np.mean([avg(r,'marker_exact_prob',k) for r in rs]) for k in range(16)];axes[1].plot(range(16),p,marker='.',label=label)
 axes[0].set_title('L24 timing component transports');axes[0].set_ylabel('Frozen-template vector projection');axes[1].set_title('Large marker peak mainly suppresses');axes[1].set_ylabel('Exact marker probability')
 for ax in axes:ax.set_xlabel('Common predicted token position modulo16');ax.grid(alpha=.2)
 axes[0].legend(fontsize=8);fig.tight_layout();fig.savefig(R/'timing_vs_output.png',dpi=160);plt.close(fig);print('WROTE FINAL_REPORT/stateprofiles/phasefigure')
if __name__=='__main__':main()
